import 'package:flutter/material.dart';class GlassContainer extends StatelessWidget {  final Widget child;  final double borderRadius;  final double blur;  final double opacity;  const GlassContainer({    super.key,    required this.child,    this.borderRadius = 16.0,    this.blur = 15.0,    this.opacity = 0.1,  });  @override  Widget build(BuildContext context) {    return Container(      decoration: BoxDecoration(        color: Colors.white.withOpacity(opacity),        borderRadius: BorderRadius.circular(borderRadius),        border: Border.all(color: Colors.white.withOpacity(0.1)),      ),      child: ClipRRect(        borderRadius: BorderRadius.circular(borderRadius),        child: child,      ),    );  }}